(function(global){
'use strict';
const RA=global.RA=global.RA||{};const D=(w,p)=>RA.D(w,p);
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+q.s,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('trinket','Trinket is recorded in English for a small ornament or object; the available etymological source does not establish a secure deeper origin, so no further root is asserted.',C('trinket.s1','饰品','The child chose a wooden trinket from the museum shop to remember the visit.','孩子从博物馆商店挑了一件木制小饰品，留作纪念。','a small trinket; decorative trinkets','可数名词，指便宜或小巧的首饰、装饰品。','木制纪念品是小型装饰物。'),M('The museum’s trinket was a priceless bridge weighing several tons, not a small decorative object.','The museum’s trinket was a small inexpensive ornament offered as a souvenir.','trinket 通常指小型装饰物，不是数吨重的桥梁。'),[Q(1,'What is a trinket?','A small decorative object or piece of jewellery','A three-part novel series','A machine for walking indoors','The source sense is a small ornament.','meaning'),Q(1,'Why did the child choose the wooden trinket?','To keep it as a small reminder of the visit','To use it as a bridge','To measure the museum floor','The object is a souvenir-sized ornament.','context'),Q(1,'Which adjective often modifies trinket?','decorative','oceanic','tribal tribunal','A trinket is commonly described as decorative.','collocation'),Q(1,'What is the reliable statement about its deeper word history here?','The deeper origin is uncertain in the available source.','It certainly comes from the word tree.','It is a Greek word for three roads.','The entry avoids claiming an unsupported root.','meaning')]);
P('trio','Trio came through Italian trio from tri- “three”; it names a group of three people or things, and a musical composition for three performers.',[
C('trio.s1','三人组合','A trio of volunteers sorted donated coats by size before the winter drive opened.','三名志愿者在冬衣募捐活动开始前按尺码整理捐赠的大衣。','a trio of musicians/friends; form a trio','可数名词，指共同组成一组的三个人或事物。','三名志愿者共同组成了小组。'),C('trio.s2','音乐','The composer wrote a trio for violin, cello, and piano.','作曲家为小提琴、大提琴和钢琴创作了一首三重奏。','piano/string trio; perform a trio','名词，指由三名演奏者演奏的音乐作品或组合。','乐曲明确安排三名演奏者。')],M('The composer called the work a trio although it was written for a full orchestra of forty musicians.','The composer called it a trio because it was written for violin, cello, and piano.','trio 的音乐义指三位演奏者或三重奏，不是四十人的完整乐团。'),[Q(1,'What was the group of coat sorters?','A trio of three volunteers','A single treasurer','A tribunal of twenty people','Sense 1 is a group of three people or things.','context'),Q(2,'What is a piano trio written for?','Three performers, such as piano, violin, and cello','A single solo singer only','An entire marching band','Sense 2 is a work performed by a trio.','meaning'),Q(1,'How many people or things make a trio?','Three','Two','Seven','Trio derives from the idea of three.','number'),Q(2,'Which phrase is natural?','perform a string trio','perform a trestle trio of eight','trio a treaty in court','A trio can be performed by a small ensemble.','collocation')]);
P('trip','Trip is recorded in English for a light step or stumble and later for a short journey; as a verb it can mean catch one’s foot, cause someone to fall, or set off a device.',[
C('trip.s1','旅行','The students took a day trip to the coastal observatory and returned before sunset.','学生们去海岸天文台进行了一日游，并在日落前返回。','take/go on a trip; business/day trip','可数名词，指去某地并通常返回的一次旅行。','当天往返符合 day trip。'),C('trip.s2','绊倒','She tripped on a raised paving stone but caught the rail before she fell.','她被凸起的铺路石绊了一下，但在摔倒前抓住了栏杆。','trip over/on something; trip and fall','不及物动词，指脚被物体绊住而失去平衡。','脚碰到凸起石块使她失去平衡。'),C('trip.s3','使绊倒/触发','A loose cable tripped the safety switch and shut down the machine.','一根松动的电缆触发了安全开关，机器随即停机。','trip a switch/alarm; trip someone up','及物动词，指使人绊倒或触发开关等装置。','电缆触发开关并导致停机。')],M('A loose cable tripped the safety switch, but the machine continued running and the switch never activated.','A loose cable tripped the safety switch, so the machine shut down.','若开关被触发，安全装置应发生反应；错句与因果冲突。'),[Q(1,'What is a day trip?','A journey to a place and usually back within a day','A three-volume novel','A fall caused by a loose cable','Sense 1 is a journey.','meaning'),Q(2,'What happened when she tripped on the stone?','Her foot caught and she nearly fell.','She completed a long journey.','She wrote a treaty.','Sense 2 is to catch one’s foot on something.','context'),Q(3,'What did the loose cable trip?','The safety switch','The students’ day trip','The coastal observatory','Sense 3 means cause a mechanism to activate.','context'),Q(3,'Which sentence uses trip transitively?','The surge tripped the circuit breaker.','I tripped over a curb.','We took a trip to the coast.','The breaker is the direct object of transitive trip.','grammar')]);
P('triple','Triple came through French from Latin triplus “threefold,” from tri- “three”; it can describe a three-part or three-times amount and can mean make or become three times as much.',[
C('triple.s1','倍数/三部分','The report found a triple increase in calls after the clinic extended its evening hours.','报告发现，诊所延长晚间开放时间后，来电数量增加到原来的三倍。','triple the amount; triple jump; triple layers','形容词，表示三部分或三倍数量。','三倍增加表明新数量是原来的三倍。'),C('triple.s2','数量变化','The company plans to triple its recycling capacity by adding two new processing lines.','公司计划增设两条处理线，将回收能力提高到原来的三倍。','costs/sales triple; triple production','动词，指使或变成原来的三倍。','新增生产线使处理能力增加至三倍。')],M('The firm tripled its output from 100 units to 150 units and claimed that 150 is three times 100.','The firm tripled its output from 100 units to 300 units.','150 是原来的 1.5 倍；triple 要达到三倍。','measurement'),[Q(1,'A triple room has…','three beds or places','two places','one hundred places','Sense 1 can describe something made up of three.','meaning'),Q(2,'What will the company do to its recycling capacity?','Increase it to three times its current level','Reduce it to one third','Keep it unchanged','Sense 2 is the verb meaning make three times as much.','context'),Q(1,'If 20 is tripled, what is the result?','60','40','200','Multiply 20 by three.','measurement'),Q(2,'Which sentence uses triple as a verb?','The new line will triple output.','The report described a triple pattern.','They booked a triple room.','In the first sentence triple means increase threefold.','grammar')]);
P('tripod','Tripod came from Greek tripodous “three-footed,” combining tri- “three” + pous “foot”; it is a three-legged support for a camera, telescope, or pot.',C('tripod.s1','摄影器材','The photographer set the camera on a tripod to keep it steady during the long exposure.','摄影师把相机架在三脚架上，以便长时间曝光时保持稳定。','camera/telescope tripod; set up a tripod','可数名词，指用三条腿支撑设备的架子。','三条支脚稳定支撑相机。'),M('The photographer balanced the camera on a tripod with only one leg touching the ground.','The photographer balanced the camera on a tripod with all three legs firmly planted.','tripod 是三脚支架，稳定使用时三条腿都应支撑地面。'),[Q(1,'What is a tripod?','A three-legged support','A three-volume book','A river entering a larger river','Tri- plus pod/foot refers to a three-legged stand.','meaning'),Q(1,'Why did the photographer use the tripod?','To keep the camera steady during a long exposure','To make the camera move faster','To display a trophy','The support prevents camera shake.','context'),Q(1,'Which object commonly stands on a tripod?','A camera','A treaty','A river tributary','Tripods are often used to support cameras.','collocation'),Q(1,'What does the Greek element pod/pous mean?','Foot','Tree','Book','The word is based on the idea of three feet.','word-formation')]);
P('trite','Trite comes from Latin tritus “worn, rubbed,” from terere “wear away”; it describes an expression or idea used so often that it has lost force or originality.',C('trite.s1','表达方式','The reviewer called the slogan trite because the same phrase appeared in dozens of advertisements.','评论者认为这句口号陈腐，因为同一句话出现在几十则广告里。','a trite phrase/cliché; sound trite','形容词，指因反复使用而失去新意或说服力。','大量重复使口号显得缺乏原创性。'),M('The reviewer called the slogan trite because nobody had ever used or heard the fresh phrase before.','The reviewer called the slogan trite because it repeated a familiar phrase used everywhere.','从未出现过的新表达不符合 trite 所说的过度陈旧。'),[Q(1,'A trite slogan is…','overused and lacking originality','newly invented and striking','a three-legged stand','The source sense is worn out through overuse.','meaning'),Q(1,'Why did the reviewer criticize the slogan?','The same phrase appeared in many advertisements.','It was used only once.','It contained a careful new argument.','Repeated use made it seem stale.','context'),Q(1,'Which noun often goes with trite?','a trite phrase','a trite tripod leg','a trite of water','Trite commonly describes phrases, remarks, or ideas.','collocation'),Q(1,'Which adjective is closest to trite?','hackneyed','novel','triumphant','Hackneyed also means overused and unoriginal.','meaning')]);
P('triumph','Triumph came through Old French from Latin triumphus, a victory celebration; its still earlier origin is uncertain. It means a great success or the joy of victory, and as a verb means achieve victory.',[
C('triumph.s1','成功','The rescue was a triumph of planning, with every family evacuated before the bridge closed.','这次救援是周密计划的胜利，所有家庭都在桥梁关闭前撤离。','a triumph of skill; a great triumph','可数名词，指重大成功或胜利。','救援按计划成功完成并保护了所有家庭。'),C('triumph.s1','喜悦','A look of triumph crossed her face when the final result confirmed the team’s win.','最终结果确认团队获胜时，她脸上浮现出胜利的喜悦。','a cry/look of triumph; celebrate a triumph','名词，也指胜利所带来的喜悦或自豪。','胜利结果引发明显的喜悦表情。'),C('triumph.s2','取得胜利','The underdogs triumphed over the defending champions in the final match.','实力较弱的一方在决赛中战胜了卫冕冠军。','triumph over an opponent; triumph in a contest','不及物动词，指在竞争或冲突中获胜。','他们在比赛中击败对手。')],M('The underdogs triumphed over the champions by losing every round and failing to score.','The underdogs triumphed over the champions by winning the final match.','连续失利且未得分与 triumph 获胜相矛盾。'),[Q(1,'Why was the rescue called a triumph?','It succeeded in evacuating every family in time.','It caused the bridge to close before evacuation.','It was a repetitive routine.','Sense 1 is a major success.','context'),Q(1,'What did her look of triumph show?','Joy or pride after victory','Fear of an upcoming test','A slight tremor','The noun can name the emotion of winning.','meaning'),Q(2,'What did the underdogs do?','They defeated the defending champions.','They tied a trestle to a tree.','They withdrew before the match.','Sense 2 is the verb meaning achieve victory.','context'),Q(2,'Which preposition commonly follows the verb triumph?','over','under of','into with','One may triumph over an opponent.','grammar')]);
P('triumphant','Triumphant is formed from triumph + -ant; it describes someone successful after a struggle or something expressing the joy of victory.',C('triumphant.s1','胜利之后','The triumphant team returned to the station carrying the cup after a difficult season.','经历艰难赛季后，获胜的队伍捧着奖杯回到车站。','triumphant winner/return; look triumphant','形容词，指经过奋斗取得成功的，或表现出胜利喜悦的。','球队克服困难并赢得比赛，随后带着奖杯返程。'),M('The triumphant team celebrated its victory after losing the final and receiving no award.','The triumphant team celebrated after winning the final and receiving the cup.','输掉决赛且未获奖不构成 triumph，也不支持 triumphant。'),[Q(1,'A triumphant team is…','successful after a struggle','certain to lose every match','a three-legged object','Triumphant describes success or victory.','meaning'),Q(1,'What made the team’s return triumphant?','It carried the cup after a difficult winning season.','It had lost the final.','It left the cup behind.','The victory and trophy explain the adjective.','context'),Q(1,'What does -ant contribute in triumphant?','Forms an adjective meaning having or expressing a quality','Makes the word a plural noun','Means “without victory”','Triumph + -ant forms an adjective.','word-formation'),Q(1,'Which phrase is natural?','a triumphant return','a triumphant defeat with no success','triumphant of a treadmill','A return after victory can be described as triumphant.','collocation')]);
P('trivial','Trivial comes from Latin trivialis “commonplace, of the crossroads,” from trivium “place where three roads meet”; it means unimportant, or focused on petty matters.',[
C('trivial.s1','重要程度','The committee rejected the complaint as trivial because the spelling error did not change the contract.','委员会认为这项投诉无关紧要，因为拼写错误并未改变合同内容。','a trivial detail/matter; seem trivial','形容词，表示不重要或影响很小。','拼写错误没有改变合同的效力。'),C('trivial.s2','琐碎纠结','The discussion became trivial when the panel spent an hour arguing about the color of the folder.','小组花了一小时争论文件夹的颜色，讨论因此变得琐碎。','trivial concerns; focus on trivialities','形容人、谈论或关注点只纠缠于琐碎事项。','无关紧要的颜色问题占用了过多讨论时间。')],M('The committee called the spelling issue trivial even though that single letter changed who legally owned the property.','The committee called the harmless spelling issue trivial because it changed no legal meaning.','改变财产所有权的错误具有重大影响，不能称为 trivial。'),[Q(1,'Why was the spelling error considered trivial?','It did not change the contract’s meaning.','It transferred ownership of the property.','It caused the bridge to collapse.','Sense 1 means unimportant or minor.','context'),Q(2,'What made the discussion trivial?','The panel focused on a minor folder color for an hour.','The panel resolved a major safety crisis.','The panel signed an international treaty.','Sense 2 concerns excessive focus on petty matters.','meaning'),Q(1,'Which phrase is natural?','a trivial detail','a trivial tributary of three','a trivial treaty with no paper','Trivial commonly modifies details or matters.','collocation'),Q(2,'Which behavior is trivializing the meeting’s purpose?','Spending most of it on a petty issue','Resolving the main safety concern','Reviewing the evidence carefully','The second sense criticizes attention to unimportant matters.','distinction')]);
P('trivialize','Trivialize is formed from trivial + -ize; it means make a serious issue seem less important or treat something as if it had little value.',[
C('trivialize.s1','淡化问题','The spokesperson apologized for appearing to trivialize the safety risk during the press conference.','发言人就自己在记者会上似乎淡化安全风险一事道歉。','trivialize a risk/problem; avoid trivializing','及物动词，指使严重问题显得不重要。','道歉针对的是把安全风险说得不严重。'),C('trivialize.s2','轻视价值','The museum’s new label trivialized the workers’ contribution by describing decades of skilled labor as “just routine.”','博物馆的新说明把几十年的熟练劳动说成“只是日常工作”，从而轻视了工人的贡献。','trivialize someone’s work/experience; trivialize a contribution','及物动词，也可指轻视某事物的价值或意义。','把长期专业劳动简化成“只是日常”削弱了其价值。')],M('The report trivialized the hazard by clearly explaining its severity, likely consequences, and the urgent need to act.','The report trivialized the hazard by dismissing it as harmless despite evidence of serious consequences.','认真说明危险后果并不淡化问题；错例前后矛盾。'),[Q(1,'What does it mean to trivialize a safety risk?','Make it seem less serious than it is','Describe its danger accurately','Measure it with a tripod','Sense 1 is minimizing a serious issue.','meaning'),Q(2,'How did the museum label trivialize the workers?','It called decades of skilled work “just routine.”','It documented their expertise in detail.','It gave them a tribute concert.','Sense 2 is treating someone’s contribution as having little value.','context'),Q(1,'Which verb is closest to trivialize in the risk sentence?','downplay','emphasize','investigate','Trivialize can mean make something seem less important.','meaning'),Q(2,'Which phrase is grammatical?','trivialize a contribution','trivialize to a contribution','trivialize of the workers contribution','Trivialize is transitive and takes a direct object.','grammar')]);
P('trolley','Trolley is an English word of uncertain deeper origin; it names a small wheeled cart for carrying goods or, especially in American usage, a streetcar.',[
C('trolley.s1','手推车','The porter loaded two suitcases onto a trolley and wheeled them toward the hotel lift.','行李员把两个行李箱放上手推车，推向酒店电梯。','luggage/shopping trolley; push a trolley','可数名词，指运送物品的小型带轮车辆。','行李员用车轮搬运行李。'),C('trolley.s2','有轨电车','In the old photograph, a trolley carried passengers along the city’s electric street railway.','在那张老照片里，一辆有轨电车沿城市电气轨道载客。','trolley car; ride the trolley','美式英语中可指城市有轨电车。','车辆沿轨道运送乘客。')],M('The porter put the suitcases on a trolley, which was a large fixed railway engine carrying no luggage.','The porter put the suitcases on a small wheeled luggage trolley.','行李 trolley 是小型推车，不是固定的铁路机车。'),[Q(1,'What did the porter push toward the lift?','A wheeled cart carrying luggage','An electric streetcar on rails','A tripod','Sense 1 is a small cart for goods.','context'),Q(2,'What does trolley mean in the American street-railway example?','A streetcar','A shopping basket carried by hand','A legal panel','Sense 2 is the tram meaning.','meaning'),Q(1,'Which phrase is natural for the cart sense?','push a luggage trolley','sign a luggage trolley','trolley the treaty with permission','People push wheeled trolleys.','collocation'),Q(2,'Which clue points to the streetcar sense?','It carries passengers along electric rails.','It holds suitcases in a hotel.','It is carried in a pocket.','The rails and passenger service identify a tram.','context')]);
P('trolly','Trolly is a variant spelling of trolley, the English name for a small wheeled cart and, in some usage, a streetcar.',C('trolly.s1','行李搬运','The station attendant placed the heavy cases on a trolly and pushed them to the platform.','车站工作人员把沉重的箱子放在手推车上，推到站台。','luggage trolly; push a trolly','可数名词，拼写变体，指搬运行李或货物的小推车。','行李被放在车上并由工作人员推动。'),M('The attendant used a trolly by lifting the cases with no wheeled cart or other support.','The attendant loaded the cases onto a wheeled trolly and pushed it to the platform.','trolly/trolley 在此指带轮手推车；徒手搬箱子不是使用推车。'),[Q(1,'What is a trolly in the station scene?','A small wheeled cart for luggage','A large ocean trench','A three-part book','The spelling variant has the cart sense.','meaning'),Q(1,'What happened to the cases?','They were placed on the cart and pushed to the platform.','They were left inside a river.','They were used as a tripod.','The context describes the cart carrying luggage.','context'),Q(1,'How does trolly relate to trolley?','It is a variant spelling of the same word.','It is the plural of treaty.','It is a different word for a treetop.','Both spellings can name the cart; trolley is the commoner spelling.','distinction'),Q(1,'Which phrase fits?','push a luggage trolly','push a trolly through the sky','sign a trolly into law','A wheeled cart is pushed.','collocation')]);
P('troop','Troop came through French troupe, from Italian truppa “company or band”; it can mean soldiers, a group of people or animals, or move together in a group.',[
C('troop.s1','军队','A troop of soldiers guarded the bridge while engineers inspected the damaged supports.','一队士兵守卫着桥梁，工程师则检查受损的支撑结构。','troops of soldiers; deploy/send troops','名词，指成群的士兵；troops 常作复数。','士兵集体执行守卫任务。'),C('troop.s2','群体','A troop of monkeys crossed the forest path just before the research team arrived.','研究队抵达前，一群猴子刚好穿过了林间小路。','a troop of monkeys/scouts; troop together','名词，指一群人或动物。','猴子作为群体一起移动。'),C('troop.s3','成群行动','The children trooped into the hall after the guide opened the doors.','导游打开门后，孩子们成群地走进大厅。','troop into/out of a place; troop along','动词，表示一群人一起移动或行进。','多个孩子一起进入大厅。')],M('The children trooped into the hall one by one, with every child separated by several hours.','The children trooped into the hall together after the guide opened the doors.','troop 作动词表示成群移动，不是彼此隔开数小时单独到达。'),[Q(1,'Who guarded the bridge?','A troop of soldiers','A trio of composers','A group of treehoppers','Sense 1 refers to soldiers as a group.','context'),Q(2,'What crossed the forest path?','A group of monkeys','A tribunal','A trolley car','Sense 2 can describe a group of animals.','context'),Q(3,'What does “the children trooped into the hall” mean?','They entered together as a group.','Each arrived alone hours apart.','They repaired the hall floor.','Sense 3 is the verb for group movement.','meaning'),Q(3,'Which preposition fits this use?','troop into the hall','troop under the treaty as a noun','troop to a tricycle by threefold','Troop into describes a group entering a place.','grammar')]);
P('trooper','Trooper is formed from troop + agent suffix -er; it can mean a cavalry member, a state police officer, or an ordinary service member spoken of with respect.',[
C('trooper.s1','执法/骑兵','The state trooper directed traffic around the flooded underpass until the road reopened.','州警察在道路重新开放前指挥车辆绕行被淹的地下通道。','state trooper; cavalry trooper','可数名词，指州警察或骑兵部队成员。','该人员执行州警务并指挥交通。'),C('trooper.s2','军中称呼','After thirty years of service, the veteran was remembered as a dependable old trooper.','服役三十年后，这位老兵被人们称作可靠的老兵。','a tough/old trooper; fellow trooper','口语中可尊敬地称普通军人或长期服役者为 trooper。','old trooper 表示对长期服役者的敬意。')],M('The state trooper directed traffic by abandoning the road and refusing to help motorists near the flooded underpass.','The state trooper directed traffic around the flooded underpass.','指挥交通的 trooper 正在执行警务；弃岗不管与之相反。'),[Q(1,'What did the state trooper do?','Directed traffic around the flooded road','Wrote a trilogy','Measured an earth tremor','Sense 1 includes a state police officer.','context'),Q(2,'What does “old trooper” respectfully suggest?','A long-serving, dependable service member','A person who has never served','A three-legged camera stand','Sense 2 is an appreciative informal label.','meaning'),Q(1,'Which phrase is common in the police sense?','state trooper','state treetop','state trinket','State trooper names a state police officer.','collocation'),Q(2,'What does -er contribute in trooper?','A person associated with a troop or service role','A medical treatment','A three-month period','The suffix forms a person noun from troop.','word-formation')]);
P('troops','Troops is the plural of troop; it refers to soldiers as a group or to a country’s armed services collectively.',[
C('troops.s1','军事行动','The government sent troops to assist residents after the coastal storm damaged the roads.','沿海风暴损坏道路后，政府派出部队协助居民。','send/deploy/withdraw troops; troops arrive','复数名词，指一批士兵或军队人员。','士兵被派去协助受灾居民。'),C('troops.s2','武装力量','The country’s troops include the army, navy, and air force.','该国的武装力量包括陆军、海军和空军。','the country’s troops; armed troops','复数形式也可统称一个国家的武装力量。','句子把陆海空军作为国家整体武装力量来描述。')],M('The government sent troops to help the residents, but none of the soldiers or service members were deployed.','The government sent troops, including soldiers and service members, to help the residents.','派出 troops 意味派出军队人员；说没有任何人部署与此矛盾。'),[Q(1,'Why did the government send troops?','To help residents after the storm','To perform a musical trio','To inspect a family tree','Sense 1 is soldiers sent as a group.','context'),Q(2,'What can “the country’s troops” refer to collectively?','Its armed services','Its tree population','Its legal tribunals','Sense 2 can refer to a nation’s armed forces.','meaning'),Q(1,'Which verb naturally goes with troops?','deploy troops','treble troops to three times as a noun','tress troops into a poem','Governments may deploy or send troops.','collocation'),Q(2,'Why is troops plural here?','It refers to multiple service members or the armed forces.','It names a single soldier only.','It is an adjective meaning timid.','Troops is the plural form and commonly refers to military personnel collectively.','grammar')]);
P('trophy','Trophy came through French trophée from Latin tropaeum and Greek tropaion, a monument of victory; it names an award or an object kept as evidence of success.',[
C('trophy.s1','竞赛奖品','The school’s robotics team placed the trophy beside the winning design after the final round.','学校机器人队在决赛后把奖杯放在获胜作品旁边。','win/hold a trophy; trophy cup','可数名词，指比赛胜者获得的奖杯或奖品。','奖杯授予比赛获胜者。'),C('trophy.s2','成功纪念物','The climber kept a photograph of the summit as a trophy of the expedition.','登山者把峰顶照片留作这次探险成功的纪念。','a trophy of success; trophy collection','名词，也可指保存下来作为成功或胜利标志的物品。','照片记录了探险者的成就。')],M('The losing team received the winner’s trophy before the final began and without competing.','The winning team received the trophy after the final competition.','trophy 是获胜后授予的奖品；未比赛的失败方不应提前获得冠军奖杯。'),[Q(1,'What did the robotics team place beside its design?','The competition trophy','A treaty','A trolley','Sense 1 is an award for winning.','context'),Q(2,'Why did the climber keep the summit photograph?','As a reminder and sign of the expedition’s success','As a legal payment to an emperor','As a tree diagram','Sense 2 is an object kept to represent an achievement.','meaning'),Q(1,'Which verb collocates with trophy?','win a trophy','tread a trophy on a road','trophy a meeting into the hall','A competitor can win a trophy.','collocation'),Q(2,'What does a trophy of an expedition represent?','A sign of achievement','A record of a failed attempt only','A type of foot pedal','The object symbolizes the success of the expedition.','meaning')]);
P('tropic','Tropic came through Latin tropicus from Greek tropikos “of a turn,” from tropos “turn”; it names either latitude where the sun reaches its farthest north or south, or the hot region between them.',[
C('tropic.s1','地理纬线','The Tropic of Cancer marks the northern latitude at which the sun can appear directly overhead.','北回归线标示太阳可能直射到的最北纬度。','Tropic of Cancer/Capricorn; the tropics','名词，指北回归线或南回归线之一。','北回归线是太阳直射位置的北界。'),C('tropic.s2','热带区域','The expedition crossed the tropic and entered the hot region between the two major latitude lines.','探险队越过回归线，进入两条主要纬线之间的炎热区域。','the tropic region; live in the tropics','也可指两回归线之间的热带地区。','地理位置位于两条回归线之间。')],M('The Tropic of Cancer lies at the South Pole and marks a latitude in the Antarctic.','The Tropic of Cancer lies north of the equator and marks the northernmost latitude of the overhead sun.','北回归线位于北半球，不在南极。'),[Q(1,'What does the Tropic of Cancer mark?','The northern latitude where the sun can be overhead','The South Pole','A mountain trench','Sense 1 is one of the two named lines of latitude.','meaning'),Q(2,'Where is the hot tropic region?','Between the Tropic of Cancer and the Tropic of Capricorn','Beyond the Arctic Circle only','Inside a museum treasury','Sense 2 is the hot region between the lines.','meaning'),Q(1,'Which proper name is standard?','Tropic of Capricorn','Treadmill of Capricorn','Tribunal of Capricorn','Tropic of Capricorn is the southern line of latitude.','collocation'),Q(2,'Which clue indicates the regional sense?','The expedition entered the hot zone between the two lines.','A map marked one latitude line.','A committee reviewed evidence.','A region between both lines is the hot tropic zone.','context')]);
P('tropical','Tropical came through French from Latin tropicus, from Greek tropikos “of a turn”; it describes hot regions near the equator, extreme heat, or strongly emotional behavior.',[
C('tropical.s1','气候与地区','The island’s tropical climate supports mangroves, orchids, and warm-water coral reefs.','岛上的热带气候适宜红树林、兰花和温水珊瑚礁生长。','tropical climate/forest; tropical region','形容词，表示与赤道附近炎热地区有关的。','列出的生态环境适应温暖湿润气候。'),C('tropical.s2','非常炎热/强烈','The meeting became tropical when both negotiators shouted and gestured across the table.','双方谈判代表隔着桌子大声争论并挥手时，会议气氛变得异常激烈。','tropical heat; tropical passions','较少见或修辞性用法，可表示酷热或情绪强烈。','争吵场面显示情绪非常激烈。')],M('The tropical greenhouse stayed below freezing all year and could not support warm-region plants.','The tropical greenhouse stayed warm enough for plants adapted to hot regions.','热带通常与温暖气候相关；全年冰点以下不符此义。'),[Q(1,'What does tropical climate support in the example?','Warm-region plants and coral reefs','Arctic ice only','A tribunal and treasury','Sense 1 describes equatorial warmth and ecosystems.','context'),Q(2,'Why did the meeting become tropical in the figurative use?','The negotiators grew intensely emotional.','Everyone became silent and calm.','A palm tree appeared in the room.','Sense 2 can suggest strong passions or heat.','meaning'),Q(1,'Which phrase is natural for sense 1?','a tropical forest','a tropical trestle tribunal','a tropical only in winter frost','Tropical commonly modifies climate, forest, or region.','collocation'),Q(2,'Which meaning of tropical fits the heated argument?','Intensely emotional','Exactly three-sided','A legal agreement','The figurative sense describes strong passions.','meaning')]);
P('tropics','Tropics is the plural form of tropic; it names the hot regions between the Tropic of Cancer and the Tropic of Capricorn and can describe their hot, humid weather.',[
C('tropics.s1','地理区域','The ship entered the tropics after crossing the Tropic of Cancer on its southbound voyage.','船只向南航行越过北回归线后进入了热带地区。','in/near the tropics; travel to the tropics','复数名词，指南北回归线之间的地球区域。','越过北回归线向南即进入两回归线之间的热带。'),C('tropics.s2','气候','The visitors needed light clothing to adjust to the heat and humidity of the tropics.','游客需要穿轻便衣物，以适应热带的炎热与潮湿。','heat/humidity of the tropics; tropical weather','也可指热带地区典型的炎热潮湿气候。','轻便衣物是为了适应炎热潮湿天气。')],M('The ship entered the tropics after sailing north into the Arctic beyond the Tropic of Cancer.','The ship entered the tropics after sailing south across the Tropic of Cancer.','从北回归线继续向北进入北极方向，不是进入两条回归线之间的热带。'),[Q(1,'Where are the tropics geographically?','Between the Tropic of Cancer and the Tropic of Capricorn','Beyond the Arctic Circle','At the North Pole','Sense 1 describes a geographical zone.','meaning'),Q(2,'What did visitors need to adjust to?','The heat and humidity typical of the tropics','The cold of the polar night','A tribunal’s legal rules','Sense 2 refers to the climate.','context'),Q(1,'Which phrase is common?','travel to the tropics','travel to the treadle','travel the tropics of a treaty','People travel to or live in the tropics.','collocation'),Q(2,'What clothing would help in the described tropics?','Light, breathable clothing','A heavy insulated polar suit only','A trestle frame','The context describes hot, humid conditions.','context')]);
P('tropism','Tropism is formed from Greek tropos “turn” + -ism; in biology it names directed growth or movement in response to an external stimulus such as light or gravity.',C('tropism.s1','生物学','The seedling’s positive phototropism bent its stem toward the window as it grew.','幼苗的正向向光性使它在生长时把茎弯向窗户。','phototropism; gravitropism; positive tropism','可数名词，指生物体对外界刺激作出的定向生长或运动反应。','茎朝光源定向弯曲，是向光性反应。'),M('The seedling showed phototropism by bending away from every light source and toward a dark wall.','The seedling showed phototropism by bending toward the light from the window.','phototropism 是对光的定向生长；错句方向相反。'),[Q(1,'What is tropism?','Directed growth or movement in response to a stimulus','A random motion unrelated to the environment','A formal three-part book','The source sense is a directed biological response.','meaning'),Q(1,'Why did the seedling bend toward the window?','It responded directionally to light.','It responded to a treaty.','Its roots formed a tripod.','The context describes phototropism.','context'),Q(1,'What stimulus causes phototropism?','Light','A musical treble','A legal trial','Photo- refers to light in phototropism.','word-formation'),Q(1,'Which example is a tropism?','A plant stem grows toward a light source.','A rock lies still on a shelf.','A trophy is displayed in a case.','The plant’s directed growth responds to an external stimulus.','meaning')]);
})(typeof window!=='undefined'?window:globalThis);
